#include <stdio.h>
#include <stdlib.h>
static void callback_a(void) { fputs("callback-A\n", stdout); }
static void callback_b(void) { fputs("callback-B\n", stdout); }
int arm_exit_hooks(void) {
    int status = atexit(callback_a) + atexit(callback_b);
    fputs("native-before\n", stdout);
    return status;
}
